using System.Windows.Media;
using DomainConsole.Shared;
namespace DomainConsole;
public partial class MainWindow {
 readonly List<TargetRecord> adActivity=Store.Read("ad-activity.json",new List<TargetRecord>());
 readonly Dictionary<string,Task<RebootSnapshot?>> statusReads=new(StringComparer.OrdinalIgnoreCase);
 readonly SemaphoreSlim statusSlots=new(3);readonly Dictionary<string,string> statusLimitations=new(StringComparer.OrdinalIgnoreCase);
 Task<RebootSnapshot?> ReadClientStatus(ComputerRow row,CancellationToken token=default,bool force=false){if(statusReads.TryGetValue(row.Host,out var pending))return pending;if(!force&&!ReadDue34(row.Host+"|флаги и аптайм"))return Task.FromResult<RebootSnapshot?>(null);
  if(!force&&rebootSnapshots.TryGetValue(row.Host,out var cached)&&DateTimeOffset.TryParse(cached.UptimeReceivedUtc,out var at)&&DateTimeOffset.UtcNow>=at&&DateTimeOffset.UtcNow-at<TimeSpan.FromSeconds(45)&&cached.UptimeSeconds.HasValue&&ConnectionFresh(row.Host))return Task.FromResult<RebootSnapshot?>(cached);
  var task=ReadClientCore(row,token);statusReads[row.Host]=task;return task;
 }
 async Task<RebootSnapshot?> ReadClientCore(ComputerRow row,CancellationToken token){await Task.Yield();bool entered=false;try{
  if(row.Target.AdDisabled)return null;var target=ConnectionStore.Capture(row.Target);var address=ConnectionStore.Address(target);if(address.Length>0&&!ConnectionStore.CanConnect(target)){statusLimitations[row.Host]="Нет учётных данных для IP; подключение не проверено";return null;}
  await statusSlots.WaitAsync(token);entered=true;var result=await remote.ReadRebootState(target,token);if(token.IsCancellationRequested||closing||!CurrentEndpoint(target))return null;ReadSucceeded34(row.Host,"флаги и аптайм");ConnectionSucceeded(row.Host);if(result.Error.Length>0)statusLimitations[row.Host]=result.Error;else statusLimitations.Remove(row.Host);ApplyClientSnapshot(row.Host,result);return result;
 }catch(OperationCanceledException){return null;}catch(RebootProbeException ex){ConnectionSucceeded(row.Host);RecordStatusDiagnostic(row.Host,new(){CollectedUtc=DateTime.UtcNow.ToString("o"),Error=ex.Message});return null;}catch(Exception ex){if(!token.IsCancellationRequested){if(IsReadFailure34(ex))ReadFailed34(row.Host,"флаги и аптайм",ex);else{ConnectionFailed(row.Host,ex.Message);statusLimitations[row.Host]=ShortConnectionError(ex.Message);}}return null;}finally{if(entered)statusSlots.Release();statusReads.Remove(row.Host);}}
 bool CurrentEndpoint(TargetRecord target){var current=ConnectionStore.Capture(new TargetRecord{Host=target.Host});return ConnectionStore.Address(current)==ConnectionStore.Address(target)&&ConnectionStore.Identity(current)==ConnectionStore.Identity(target);}
 bool CurrentIdentity(TargetRecord target)=>!ConnectionStore.Profiles.TryGetValue(target.Host,out var profile)||profile.Identity.Length==0||target.ConnectionIdentity==profile.Identity;
 void ApplyClientSnapshot(string host,RebootSnapshot next){
  rebootSnapshots.TryGetValue(host,out var old);if(old!=null&&DateTimeOffset.TryParse(old.CollectedUtc,out var prior)&&DateTimeOffset.TryParse(next.CollectedUtc,out var collected)&&collected<prior)return;RebootSnapshotPolicy.Merge(old,next);if(old!=null&&next.UptimeSeconds==null&&RebootSnapshotPolicy.SameBoot(old,next)){next.UptimeSeconds=old.UptimeSeconds;next.UptimeReceivedUtc=old.UptimeReceivedUtc;next.UptimeCollectedUtc=old.UptimeCollectedUtc.Length>0?old.UptimeCollectedUtc:old.CollectedUtc;}
  if(next.UptimeSeconds.HasValue&&next.UptimeReceivedUtc.Length==0)next.UptimeReceivedUtc=DateTime.UtcNow.ToString("o");
  if(RebootSnapshotPolicy.NewBoot(old,next))Event31(host,"boot",next.BootUtc,"Новая загрузка Windows подтверждена","Success",UptimeHint(host),next.CollectedUtc);
  rebootSnapshots[host]=next;Store.Write("reboot-snapshots.json",rebootSnapshots);RecordStatusDiagnostic(host,next);ObserveUnplannedReturn(host,old,next);ReconcileRebootHistory(host,next);
 }
 public static string Age(TimeSpan value)=>value<TimeSpan.Zero?"время некорректно":value.TotalMinutes<1?"менее минуты":value.TotalDays>=1?(int)value.TotalDays+" д "+value.Hours+" ч":value.TotalHours>=1?(int)value.TotalHours+" ч "+value.Minutes+" мин":(int)value.TotalMinutes+" мин";
 string UptimeText(string host){if(!rebootSnapshots.TryGetValue(host,out var s)||!s.UptimeSeconds.HasValue||s.UptimeSeconds<0)return "Аптайм не получен";bool fresh=ConnectionFresh(host)&&DateTimeOffset.TryParse(s.UptimeReceivedUtc,out var received)&&DateTimeOffset.UtcNow>=received&&DateTimeOffset.UtcNow-received<TimeSpan.FromSeconds(90);var age=TimeSpan.FromSeconds(s.UptimeSeconds.Value);return "Работает: "+Age(age)+(fresh?"":" (снимок)");}
 string UptimeHint(string host)=>rebootSnapshots.TryGetValue(host,out var s)?"Загрузка Windows: "+LocalDateConverter.Format(s.BootUtc)+"\nСнимок клиента: "+LocalDateConverter.Format(s.UptimeCollectedUtc.Length>0?s.UptimeCollectedUtc:s.CollectedUtc):"Время загрузки ещё не прочитано с клиента";
 string LinkKind(string host)=>statusLimitations.GetValueOrDefault(host,"").StartsWith("Нет учётных")?"Unknown":clientConnections.TryGetValue(host,out var c)?c.Error.Length>0?(c.Error.Contains("введите учётные",StringComparison.OrdinalIgnoreCase)?"Unknown":AccessError(c.Error)?"Access":"Unreachable"):ConnectionFresh(host)?"Connected":"SavedConnected":"Unknown";
 string LinkHint(ComputerRow row){var kind=LinkKind(row.Host);var text=kind switch {"Connected"=>"Связь WinRM подтверждена","SavedConnected"=>"Был доступен; сохранённый результат проверки","Access"=>"Отказано в доступе WinRM","Unreachable"=>"WinRM недоступен; это не доказывает выключение ПК",_=>"Текущая доступность не проверена"};if(clientConnections.TryGetValue(row.Host,out var c))text+="\nПоследняя попытка: "+c.LastAttempt.ToLocalTime().ToString("dd.MM.yyyy HH:mm:ss")+"\n"+(c.LastSuccess==default?"Успешный ответ клиента ещё не получен":"Последний ответ: "+Age(DateTimeOffset.UtcNow-c.LastSuccess)+" назад · "+c.LastSuccess.ToLocalTime().ToString("dd.MM.yyyy HH:mm:ss"))+(c.Error.Length>0?"\n"+ConnectionBrief31(c.Error):"");if(statusLimitations.TryGetValue(row.Host,out var limit)&&limit.StartsWith("Нет учётных"))text+="\n"+limit;if(DateTimeOffset.TryParse(row.Target.AdLastLogonUtc,out var ad))text+="\nАктивность учётной записи в AD (приблизительно): "+ad.ToLocalTime().ToString("dd.MM.yyyy HH:mm")+(ad>DateTimeOffset.UtcNow?" · дата в будущем":"")+"\nСнимок AD: "+LocalDateConverter.Format(row.Target.AdCollectedUtc);return text;}
 async Task RefreshDirectoryActivity(CancellationToken token){try{var entries=await Task.Run(DirectoryReader.Read,token).WaitAsync(TimeSpan.FromSeconds(25),token);if(token.IsCancellationRequested||closing)return;foreach(var row in Computers.Where(r=>r.OU!="Ручные подключения")){var known=entries.FirstOrDefault(t=>t.Host.Equals(row.Host,StringComparison.OrdinalIgnoreCase)&&(row.Target.DirectoryId.Length==0||row.Target.DirectoryId==t.DirectoryId));if(known!=null){row.Target.DirectoryId=known.DirectoryId;row.Target.AdLastLogonUtc=known.AdLastLogonUtc;row.Target.AdCollectedUtc=known.AdCollectedUtc;row.Target.AdDisabled=known.AdDisabled;}}adActivity.Clear();adActivity.AddRange(Computers.Where(r=>r.Target.DirectoryId.Length>0).Select(r=>r.Target).Select(t=>new TargetRecord{Host=t.Host,DirectoryId=t.DirectoryId,AdLastLogonUtc=t.AdLastLogonUtc,AdCollectedUtc=t.AdCollectedUtc,AdDisabled=t.AdDisabled}).ToList());Store.Write("ad-activity.json",adActivity);Store.Write("computers.json",Computers.Where(r=>r.OU!="Ручные подключения").Select(r=>new TargetRecord{Name=r.Name,Host=r.Host,OU=r.OU,OS=r.OS,DirectoryId=r.Target.DirectoryId,AdLastLogonUtc=r.Target.AdLastLogonUtc,AdCollectedUtc=r.Target.AdCollectedUtc,AdDisabled=r.Target.AdDisabled,Status="Не проверен"}).ToList());}catch(Exception ex){OverviewProgress.Text="Данные AD не обновлены: "+ShortConnectionError(ex.Message);}}
}

